7	import { BaseTokenStorage } from './base-token-storage.js';
8	import type { OAuthCredentials, SecretStorage } from './types.js';
9	import { coreEvents } from '../../utils/events.js';
10	import { KeychainService } from '../../services/keychainService.js';
11	import {
12	  KEYCHAIN_TEST_PREFIX,
13	  SECRET_PREFIX,
14	} from '../../services/keychainTypes.js';
15	
16	export class KeychainTokenStorage
17	  extends BaseTokenStorage
18	  implements SecretStorage
19	{
20	  private readonly keychainService: KeychainService;
21	
22	  constructor(serviceName: string) {
23	    super(serviceName);
24	    this.keychainService = new KeychainService(serviceName);
25	  }
26	
27	  async getCredentials(serverName: string): Promise<OAuthCredentials | null> {
28	    try {
29	      const sanitizedName = this.sanitizeServerName(serverName);
30	      const data = await this.keychainService.getPassword(sanitizedName);
31	
32	      if (!data) {
33	        return null;
34	      }
35	
36	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
37	      const credentials = JSON.parse(data) as OAuthCredentials;
38	
39	      if (this.isTokenExpired(credentials)) {
40	        return null;
41	      }
42	
43	      return credentials;
44	    } catch (error) {
45	      if (error instanceof SyntaxError) {
46	        throw new Error(`Failed to parse stored credentials for ${serverName}`);
47	      }
48	      throw error;
49	    }
50	  }
51	
52	  async setCredentials(credentials: OAuthCredentials): Promise<void> {
53	    this.validateCredentials(credentials);
54	
55	    const sanitizedName = this.sanitizeServerName(credentials.serverName);
56	    const updatedCredentials: OAuthCredentials = {
57	      ...credentials,
58	      updatedAt: Date.now(),
59	    };
60	
61	    const data = JSON.stringify(updatedCredentials);
62	    await this.keychainService.setPassword(sanitizedName, data);
63	  }
64	
65	  async deleteCredentials(serverName: string): Promise<void> {
66	    const sanitizedName = this.sanitizeServerName(serverName);
67	    const deleted = await this.keychainService.deletePassword(sanitizedName);
68	
69	    if (!deleted) {
70	      throw new Error(`No credentials found for ${serverName}`);
71	    }
72	  }
73	
74	  async listServers(): Promise<string[]> {
75	    try {
76	      const credentials = await this.keychainService.findCredentials();
77	      return credentials
78	        .filter(
79	          (cred) =>
80	            !cred.account.startsWith(KEYCHAIN_TEST_PREFIX) &&
81	            !cred.account.startsWith(SECRET_PREFIX),
82	        )
83	        .map((cred: { account: string }) => cred.account);
84	    } catch (error) {
85	      coreEvents.emitFeedback(
86	        'error',
87	        'Failed to list servers from keychain',
88	        error,
89	      );
90	      return [];
91	    }
92	  }
93	
94	  async getAllCredentials(): Promise<Map<string, OAuthCredentials>> {
95	    const result = new Map<string, OAuthCredentials>();
96	    try {
97	      const credentials = (await this.keychainService.findCredentials()).filter(
98	        (c) =>
99	          !c.account.startsWith(KEYCHAIN_TEST_PREFIX) &&
100	          !c.account.startsWith(SECRET_PREFIX),
101	      );
102	
103	      for (const cred of credentials) {
104	        try {
105	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
106	          const data = JSON.parse(cred.password) as OAuthCredentials;
107	          if (!this.isTokenExpired(data)) {
108	            result.set(cred.account, data);
109	          }
110	        } catch (error) {
111	          coreEvents.emitFeedback(
112	            'error',
113	            `Failed to parse credentials for ${cred.account}`,
114	            error,
115	          );
116	        }
117	      }
118	    } catch (error) {
119	      coreEvents.emitFeedback(
120	        'error',
121	        'Failed to get all credentials from keychain',
122	        error,
123	      );
124	    }
125	
126	    return result;
127	  }
128	
129	  async clearAll(): Promise<void> {
130	    try {
131	      const credentials = await this.keychainService.findCredentials();
132	      const errors: Error[] = [];
133	
134	      for (const cred of credentials) {
135	        try {
136	          await this.deleteCredentials(cred.account);
137	        } catch (error) {
138	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
139	          errors.push(error as Error);
140	        }
141	      }
142	
143	      if (errors.length > 0) {
144	        throw new Error(
145	          `Failed to clear some credentials: ${errors.map((e) => e.message).join(', ')}`,
146	        );
147	      }
148	    } catch (error) {
149	      coreEvents.emitFeedback(
150	        'error',
151	        'Failed to clear credentials from keychain',
152	        error,
153	      );
154	      throw error;
155	    }
156	  }
157	
158	  async isAvailable(): Promise<boolean> {
159	    return this.keychainService.isAvailable();
160	  }
161	
162	  async setSecret(key: string, value: string): Promise<void> {
163	    await this.keychainService.setPassword(`${SECRET_PREFIX}${key}`, value);
164	  }
165	
166	  async getSecret(key: string): Promise<string | null> {
167	    return this.keychainService.getPassword(`${SECRET_PREFIX}${key}`);
168	  }
169	
170	  async deleteSecret(key: string): Promise<void> {
171	    const deleted = await this.keychainService.deletePassword(
172	      `${SECRET_PREFIX}${key}`,
173	    );
174	    if (!deleted) {
175	      throw new Error(`No secret found for key: ${key}`);
176	    }
177	  }
178	
179	  async listSecrets(): Promise<string[]> {
180	    try {
181	      const credentials = await this.keychainService.findCredentials();
182	      return credentials
183	        .filter((cred) => cred.account.startsWith(SECRET_PREFIX))
184	        .map((cred) => cred.account.substring(SECRET_PREFIX.length));
185	    } catch (error) {
186	      coreEvents.emitFeedback(
187	        'error',
188	        'Failed to list secrets from keychain',
189	        error,
190	      );
191	      return [];
192	    }
193	  }
194	}
