7	import { promises as fs } from 'node:fs';
8	import * as path from 'node:path';
9	import * as os from 'node:os';
10	import * as crypto from 'node:crypto';
11	import { BaseTokenStorage } from './base-token-storage.js';
12	import type { OAuthCredentials } from './types.js';
13	import { GEMINI_DIR, homedir } from '../../utils/paths.js';
