15	export class FileTokenStorage extends BaseTokenStorage {
16	  private readonly tokenFilePath: string;
17	  private readonly encryptionKey: Buffer;
18	
19	  constructor(serviceName: string) {
20	    super(serviceName);
21	    const configDir = path.join(homedir(), GEMINI_DIR);
22	    this.tokenFilePath = path.join(configDir, 'mcp-oauth-tokens-v2.json');
23	    this.encryptionKey = this.deriveEncryptionKey();
24	  }
25	
26	  private deriveEncryptionKey(): Buffer {
27	    const salt = `${os.hostname()}-${os.userInfo().username}-gemini-cli`;
28	    return crypto.scryptSync('gemini-cli-oauth', salt, 32);
29	  }
30	
31	  private encrypt(text: string): string {
32	    const iv = crypto.randomBytes(16);
33	    const cipher = crypto.createCipheriv('aes-256-gcm', this.encryptionKey, iv);
34	
35	    let encrypted = cipher.update(text, 'utf8', 'hex');
36	    encrypted += cipher.final('hex');
37	
38	    const authTag = cipher.getAuthTag();
39	
40	    return iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted;
41	  }
42	
43	  private decrypt(encryptedData: string): string {
44	    const parts = encryptedData.split(':');
45	    if (parts.length !== 3) {
46	      throw new Error('Invalid encrypted data format');
47	    }
48	
49	    const iv = Buffer.from(parts[0], 'hex');
50	    const authTag = Buffer.from(parts[1], 'hex');
51	    const encrypted = parts[2];
52	
53	    const decipher = crypto.createDecipheriv(
54	      'aes-256-gcm',
55	      this.encryptionKey,
56	      iv,
57	    );
58	    decipher.setAuthTag(authTag);
59	
60	    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
61	    decrypted += decipher.final('utf8');
62	
63	    return decrypted;
64	  }
65	
66	  private async ensureDirectoryExists(): Promise<void> {
67	    const dir = path.dirname(this.tokenFilePath);
68	    await fs.mkdir(dir, { recursive: true, mode: 0o700 });
69	  }
70	
71	  private async loadTokens(): Promise<Map<string, OAuthCredentials>> {
72	    try {
73	      const data = await fs.readFile(this.tokenFilePath, 'utf-8');
74	      const decrypted = this.decrypt(data);
75	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
76	      const tokens = JSON.parse(decrypted) as Record<string, OAuthCredentials>;
77	      return new Map(Object.entries(tokens));
78	    } catch (error: unknown) {
79	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
80	      const err = error as NodeJS.ErrnoException & { message?: string };
81	      if (err.code === 'ENOENT') {
82	        return new Map();
83	      }
84	      if (
85	        err.message?.includes('Invalid encrypted data format') ||
86	        err.message?.includes(
87	          'Unsupported state or unable to authenticate data',
88	        )
89	      ) {
90	        // Decryption failed - this can happen when switching between auth types
91	        // or if the file is genuinely corrupted.
92	        throw new Error(
93	          `Corrupted token file detected at: ${this.tokenFilePath}\n` +
94	            `Please delete or rename this file to resolve the issue.`,
95	        );
96	      }
97	      throw error;
98	    }
99	  }
100	
101	  private async saveTokens(
102	    tokens: Map<string, OAuthCredentials>,
103	  ): Promise<void> {
104	    await this.ensureDirectoryExists();
105	
106	    const data = Object.fromEntries(tokens);
107	    const json = JSON.stringify(data, null, 2);
108	    const encrypted = this.encrypt(json);
109	
110	    await fs.writeFile(this.tokenFilePath, encrypted, { mode: 0o600 });
111	  }
112	
113	  async getCredentials(serverName: string): Promise<OAuthCredentials | null> {
114	    const tokens = await this.loadTokens();
115	    const credentials = tokens.get(serverName);
116	
117	    if (!credentials) {
118	      return null;
119	    }
120	
121	    if (this.isTokenExpired(credentials)) {
122	      return null;
123	    }
124	
125	    return credentials;
126	  }
127	
128	  async setCredentials(credentials: OAuthCredentials): Promise<void> {
129	    this.validateCredentials(credentials);
130	
131	    const tokens = await this.loadTokens();
132	    const updatedCredentials: OAuthCredentials = {
133	      ...credentials,
134	      updatedAt: Date.now(),
135	    };
136	
137	    tokens.set(credentials.serverName, updatedCredentials);
138	    await this.saveTokens(tokens);
139	  }
140	
141	  async deleteCredentials(serverName: string): Promise<void> {
142	    const tokens = await this.loadTokens();
143	
144	    if (!tokens.has(serverName)) {
145	      throw new Error(`No credentials found for ${serverName}`);
146	    }
147	
148	    tokens.delete(serverName);
149	
150	    if (tokens.size === 0) {
151	      try {
152	        await fs.unlink(this.tokenFilePath);
153	      } catch (error: unknown) {
154	        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
155	        const err = error as NodeJS.ErrnoException;
156	        if (err.code !== 'ENOENT') {
157	          throw error;
158	        }
159	      }
160	    } else {
161	      await this.saveTokens(tokens);
162	    }
163	  }
164	
165	  async listServers(): Promise<string[]> {
166	    const tokens = await this.loadTokens();
167	    return Array.from(tokens.keys());
168	  }
169	
170	  async getAllCredentials(): Promise<Map<string, OAuthCredentials>> {
171	    const tokens = await this.loadTokens();
172	    const result = new Map<string, OAuthCredentials>();
173	
174	    for (const [serverName, credentials] of tokens) {
175	      if (!this.isTokenExpired(credentials)) {
176	        result.set(serverName, credentials);
177	      }
178	    }
179	
180	    return result;
181	  }
182	
183	  async clearAll(): Promise<void> {
184	    try {
185	      await fs.unlink(this.tokenFilePath);
186	    } catch (error: unknown) {
187	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
188	      const err = error as NodeJS.ErrnoException;
189	      if (err.code !== 'ENOENT') {
190	        throw error;
191	      }
192	    }
193	  }
194	}
